window.kbPageData["views/entry/k-2740a51c095433e6"] = {"key":"entry/k-2740a51c095433e6","state":{"route":"entry/k-2740a51c095433e6"},"node":{"id":"k-2740a51c095433e6","mode":"k","title":"增长倍数","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["增长若干倍时现期量为基期量的增长倍数加一倍","增长倍数等于增长量除以基期量","增长n倍表示现期量为基期量的n加1倍"],"qs":["江苏 2024 B类 行测#133","江苏 2024 C类 行测#128","江苏 2025 A类 行测#120","江苏 2025 C类 行测#115"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":4,"repeatPositions":0,"directorySummary":"增长倍数是增长量与基期量的比值。若现期量比基期量增长 n 倍，则现期量是基期量的 n＋1 倍。","review":{"definition":"增长倍数是增长量与基期量的比值。若现期量比基期量增长 n 倍，则现期量是基期量的 n＋1 倍。","explanation":"现期量包含基期量和新增量，所以反推基期量时，应将现期量除以增长倍数加 1。材料给出 2023 年平板玻璃产量为 9.7 亿重量箱，比 1949 年增长 897 倍。将 9.7 亿换算为 97,000 万，再除以 898，得到 1949 年产量约为 108.0 万重量箱，低于 110 万重量箱，因此 A 项能够推出。","references":[{"source":"web-2520694c743f755f","location":"第10页，图表1，2014年和2022年的柱形标注，图源为中国音数协游戏工委","quote":"中国游戏市场实际销售收入及增长率"}],"evidence":"平板玻璃产量9.7亿重量箱，增长897倍","disposition":"独立词条","basis":"据原题和解析编释。","title":"增长倍数","related":[],"examFocus":{"江苏 2024 B类 行测#133":"区分“增长了几倍”和“是原来的几倍”，看应把哪一个量与2014年游戏市场销售收入相比。","江苏 2024 C类 行测#128":"在游戏市场销售收入数据中找出2014年和2022年的数值，用销售收入的增量与2014年的收入相比。","江苏 2025 A类 行测#120":"用现期产量和增长倍数反推1949年平板玻璃产量，统一单位后与题设上限比较。","江苏 2025 C类 行测#115":"反推1949年平板玻璃产量时，区分增长倍数与现期量相对基期量的倍数，再按同一单位核对题设上限。"}},"readings":[{"origin":"k-2740a51c095433e6","title":"增长倍数","qs":["江苏 2025 C类 行测#115"],"definition":"增长倍数是增长量与基期量的比值。若现期量比基期量增长 n 倍，则现期量是基期量的 n＋1 倍。","explanation":"现期量包含基期量和新增量，所以反推基期量时，应将现期量除以增长倍数加 1。材料给出 2023 年平板玻璃产量为 9.7 亿重量箱，比 1949 年增长 897 倍。将 9.7 亿换算为 97,000 万，再除以 898，得到 1949 年产量约为 108.0 万重量箱，低于 110 万重量箱，因此 A 项能够推出。","evidence":"平板玻璃产量9.7亿重量箱，增长897倍","doubt":"","references":[]},{"origin":"k-4b4c8b52e4192e0d","title":"增长倍数","qs":["江苏 2024 B类 行测#133"],"definition":"增长倍数是增长量相当于基期量的倍数，等于（现期量－基期量）÷基期量。现期量是基期量的多少倍，则用现期量直接除以基期量。","explanation":"第133题问2022年我国游戏市场销售收入比2014年增长多少倍，以2014年的1145亿元为基期量。按图中数据计算，（2659－1145）÷1145≈1.32，最接近A项的1.3倍。直接用2659÷1145得到约2.32，表示2022年收入是2014年的约2.32倍，对应干扰项C。原解析写成1.38倍，计算有误，正确选项仍为A。","evidence":"2022年我国游戏市场销售收入比2014年增长：","doubt":"","references":[]},{"origin":"k-7ba9e03de060545e","title":"增长倍数","qs":["江苏 2025 A类 行测#120"],"definition":"增长倍数是增长量除以基期量所得的倍数。某指标比基期增长 n 倍，现期量就是基期量的 n＋1 倍。","explanation":"第120题材料给出，2023年我国平板玻璃产量为9.7亿重量箱，比1949年增长897倍。现期量还包含原有的1倍，因此1949年产量约为97000÷898＝108.0万重量箱，低于110万重量箱，故A项可以推出。","evidence":"平板玻璃产量9.7亿重量箱，增长897倍","doubt":"","references":[]},{"origin":"k-c8a42838be4b872f","title":"增长倍数","qs":["江苏 2024 C类 行测#128"],"definition":"基期量为正时，现期量比基期量增长的倍数等于（现期量－基期量）÷基期量。现期量是基期量的倍数等于现期量÷基期量，比增长倍数多1。","explanation":"第128题以2014年为基期、2022年为现期。所附图片是酱油进出口表。顺网科技年报转载的中国音数协游戏工委图表显示，两年游戏市场实际销售收入分别为1144.81亿元和2658.84亿元，取整后与题解所列的1145亿元和2659亿元一致。按题解数据复算，（2659－1145）÷1145≈1.32，最接近A项的1.3倍。题解中的“增长1.38倍”应改为“增长约1.32倍”。","evidence":"2022年我国游戏市场销售收入比2014年增长","doubt":"","references":[{"source":"web-2520694c743f755f","location":"第10页，图表1，2014年和2022年的柱形标注，图源为中国音数协游戏工委","quote":"中国游戏市场实际销售收入及增长率"}]}]},"questions":{"江苏 2024 B类 行测#133":{"paper":"江苏 2024 B类 行测","n":133,"mod":"资料分析","src":["0ae7ac475476e5635bd7.pdf",26],"asrc":["8dd171daee6fc74e9718.pdf",43],"card":"1a9bcc6b0220767d14476416","links":[{"id":"k-2740a51c095433e6","role":"解题依据","why":"题问增长的倍数，计算时以两年的收入差额为分子、2014年收入为分母。"}]},"江苏 2024 C类 行测#128":{"paper":"江苏 2024 C类 行测","n":128,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",27],"asrc":["02d6b49839583bdaf297.pdf",38],"card":"ef76858f5d258ce06a576a98","links":[{"id":"k-2740a51c095433e6","role":"解题依据","why":"题目中的增长倍数以收入增量为分子，以基期收入为分母。"}]},"江苏 2025 A类 行测#120":{"paper":"江苏 2025 A类 行测","n":120,"mod":"资料分析","src":["98687766ac277f427cd6.pdf",25],"asrc":["4fe8e0544dd7b47699d2.pdf",39],"card":"4a013517f85757c6ae64f864","links":[{"id":"k-2740a51c095433e6","role":"解题依据","why":"增长倍数只计增加的部分，反推基期产量时分母还需计入原有的一倍。"}]},"江苏 2025 C类 行测#115":{"paper":"江苏 2025 C类 行测","n":115,"mod":"资料分析","src":["ffc394a1c160f331ec57.pdf",24],"asrc":["d1de3b437151c05b769e.pdf",35],"card":"90936bacc21651bc226bc33a","links":[{"id":"k-2740a51c095433e6","role":"解题依据","why":"增长倍数是增量与基期量的比值，反推基期量时应以增长倍数加一为除数。"}]}},"terms":{},"references":{"web-2520694c743f755f":{"name":"杭州顺网科技股份有限公司2022年年度报告全文","url":"https://static.cninfo.com.cn/finalpage/2023-04-22/1216526057.PDF#page=10"}},"topics":[],"units":{"k-2740a51c095433e6":[["江苏 2024 B类 行测#133"],["江苏 2024 C类 行测#128"],["江苏 2025 A类 行测#120"],["江苏 2025 C类 行测#115"]]}};
